using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using MapSharedProps;using MapSharedProps.EditorTools;
public static class Sanctum94Checks {
 static string Root=>Path.GetFullPath(Path.Combine(Application.dataPath,".."));
 static void Check(bool ok,string why){if(!ok)throw new Exception(why);}
 static Dictionary<string,GameObject> Build(string input,string folder){if(!AssetDatabase.IsValidFolder(folder))AssetDatabase.CreateFolder("Assets",folder.Substring(7));var p=new Dictionary<string,GameObject>();var parent=new GameObject("Review placements");SmallPropsV1.Build(input,folder,parent.transform,Shader.Find("MapSharedProps/Lit"),p);UnityEngine.Object.DestroyImmediate(parent);AssetDatabase.SaveAssets();Check(p.Count==43,"43 prefabs");return p;}
 public static void Run(){int exit=0;string output=Path.Combine(Root,"Evidence94Import");Directory.CreateDirectory(output);try{EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var p=Build(Path.Combine(Root,"Input94"),"Assets/Imported94");var rain=p["treasurechest_rainbow"];var old=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Imported89/small-treasurechest_rainbow.prefab");Check(rain.GetComponent<ChestSanctumPresentation>(),"formal presentation");Check(!rain.GetComponent<Renderer>().enabled,"legacy visual hidden");Check(rain.GetComponent<MeshCollider>().sharedMesh==old.GetComponent<MeshCollider>().sharedMesh,"Collider exact");Check(p["treasurechest_gold"].GetComponentsInChildren<Light>().Length==2,"gold lights preserved");var oldSilver=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Imported92/small-treasurechest_silver.prefab");Check(p["treasurechest_silver"].GetComponent<MeshFilter>().sharedMesh==oldSilver.GetComponent<MeshFilter>().sharedMesh,"silver visual preserved");
 var camera=new GameObject("Budget camera").AddComponent<Camera>();camera.tag="MainCamera";camera.transform.position=new Vector3(0,2,-6);var objects=new List<GameObject>();var counts=new List<int>();for(int k=0;k<5;k++){var o=(GameObject)PrefabUtility.InstantiatePrefab(rain);o.transform.position=new Vector3(k*1.3f,0,0);o.GetComponent<ChestSanctumPresentation>().SetTime(.8f);objects.Add(o);ChestSanctumPresentation.RefreshLights(camera);Check(ChestSanctumPresentation.LightCapacity<=6,"light pool capacity");counts.Add(ChestSanctumPresentation.ActiveLights);}Check(counts[0]==3&&counts.Skip(1).All(x=>x==6),"nearest two lights");camera.transform.position=new Vector3(100,0,0);ChestSanctumPresentation.RefreshLights(camera);Check(ChestSanctumPresentation.ActiveLights==0,"distance fade");foreach(var o in objects)UnityEngine.Object.DestroyImmediate(o);ChestSanctumPresentation.RefreshLights(camera);Check(ChestSanctumPresentation.LightCapacity==0,"pool cleanup");UnityEngine.Object.DestroyImmediate(camera.gameObject);
 string original=File.ReadAllText(Path.Combine(Root,"Input94","small_props.json")),temp=Path.Combine(Root,"Input94Cases");Directory.CreateDirectory(temp);File.Copy(Path.Combine(Root,"Input94","props.csv"),Path.Combine(temp,"props.csv"),true);var cases=new List<string>();foreach(string kind in new[]{"absent","version","index","nonfinite"}){var q=Build(Path.Combine(Root,"Input94Cases-"+kind),"Assets/Imported94Fallback-"+kind);Check(!q["treasurechest_rainbow"].GetComponent<ChestSanctumPresentation>()&&q["treasurechest_rainbow"].GetComponent<Renderer>().enabled,"fallback "+kind);cases.Add(kind+":43");}
 var gold=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Imported94/small-treasurechest_gold.prefab");var gm=gold.GetComponentsInChildren<MeshRenderer>().SelectMany(r=>r.sharedMaterials).First(m=>m.GetTexture("_BumpMap"));var rm=rain.GetComponentsInChildren<MeshRenderer>(true).SelectMany(r=>r.sharedMaterials).First(m=>m.shader.name=="MapSharedProps/ChestSanctum"&&m.GetFloat("_Relief")>.5);Check(gm.GetTexture("_BumpMap")==rm.GetTexture("_Normal"),"shared normal texture");Check(gm.GetTexture("_MetallicGlossMap")==rm.GetTexture("_Mask"),"shared packed texture");File.WriteAllText(Path.Combine(output,"checks.json"),"{\"pass\":true,\"prefabs\":43,\"fallbackCases\":[\""+string.Join("\",\"",cases)+"\"],\"colliderExact\":true,\"silverExact\":true,\"goldLights\":2,\"lightCounts\":["+string.Join(",",counts)+"],\"maxPool\":6,\"poolCleanup\":true,\"sharedNormalPacked\":true,\"playerExecuted\":false}");
 }catch(Exception e){Debug.LogException(e);File.WriteAllText(Path.Combine(output,"error.txt"),e.ToString());exit=1;}finally{EditorApplication.Exit(exit);}}
}
